mod graph;
use graph::{Graph,Row,combine,value};
use hec_native_ic::{fp::Fp,rng::Rng};
fn planted(f:&Fp,x:&[u64],y:&[u64],large:&[(usize,u64)],mut row:Row)->Row{let mut z=value(f,&row,x);for&(i,a)in large{z=f.add(z,f.mul(a,y[i]));}row=combine(f,&row,1,&vec![((x.len()-1)as u32,f.neg(z))],1);row}
fn directed(){let f=Fp::new(101);let x=[7,19,31,1];let y=[0,13,23,47,59];let mut g=Graph::new(4,3,101);let mut reduced=0;for large in [vec![(1,1),(2,100)],vec![(2,1),(3,1)],vec![(1,1),(3,1)],vec![(1,1),(2,1)],vec![(4,3)],vec![(3,100),(4,7)],vec![]]{let row=planted(&f,&x,&y,&large,vec![(0,2),(1,9)]);if let Some(r)=g.insert(&large,row){assert_eq!(value(&f,&r,&x),0);reduced+=1;}g.check(&x,&y);}assert!(g.stats.balanced_cycles>0&&g.stats.anchors>0&&g.stats.anchored_cycles>0&&reduced>0);let mut bad=Graph::new(1,3,101);let e=vec![(1,1)];let row=planted(&f,&x,&y,&e,vec![(0,3)]);assert!(bad.insert(&e,row.clone()).is_none());let corrupt=combine(&f,&row,1,&vec![(3,1)],1);let r=bad.insert(&e,corrupt).unwrap();assert_ne!(value(&f,&r,&x),0);println!("DIRECTED balanced_cycles={} unbalanced_anchors={} anchored_cycles={} nonunit_and_signed_coefficients=true corrupted_relation_rejected=true",g.stats.balanced_cycles,g.stats.anchors,g.stats.anchored_cycles);}
fn main(){directed();let mut all=0;for ell in [101,65537,1000003]{for seed in [1001,1002,1003]{let f=Fp::new(ell);let mut rng=Rng::new(seed);let mut x:Vec<u64>=(0..8).map(|_|rng.below(ell)).collect();x.push(1);let mut y:Vec<u64>=(0..33).map(|_|rng.below(ell)).collect();y[0]=0;let mut g=Graph::new(32,8,ell);let mut count=0;for _ in 0..1000{let n=rng.below(3)as usize;let large:Vec<_>=(0..n).map(|_|(1+rng.below(32)as usize,1+rng.below(ell-1))).collect();let mut row=vec![];for _ in 0..4{let i=rng.below(8)as u32;let a=rng.below(ell);row=combine(&f,&row,1,&vec![(i,a)],1);}let row=planted(&f,&x,&y,&large,row);if let Some(r)=g.insert(&large,row){assert_eq!(value(&f,&r,&x),0,"reduced_original_witness_residual");count+=1;}g.check(&x,&y);}assert!(count>900);all+=count;println!("COHORT ell={ell} seed={seed} edges=1000 reduced_rows={count} stats={:?} all_vertex_invariants_after_every_edge=true",g.stats);}}println!("PASS native_two_large_prime_graph_edges=9000 reduced_rows={all} full_affine_invariants=true actual_curve_DLP_or_speedup_not_tested=true");}
